INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (137, 1, 'docker run 은 무엇을 할까', '`docker run nginx` 를 처음 실행하면 무슨 일이 일어날까요?', '이미지가 내 컴퓨터에 없으면 어떻게 될지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["이미지만 내려받고 아무것도 실행하지 않는다", "기존 컨테이너를 찾아서 다시 시작한다", "이미지가 없으면 내려받고, 그 이미지로 새 컨테이너를 만들어 실행한다", "이미지를 삭제한다"]', 2, '`docker run` 은 "받기(pull) + 만들기(create) + 시작하기(start)"를 한 번에 합니다. 실행할 때마다 새 컨테이너가 하나 더 만들어져요.', NULL, NULL, NULL, NULL),
  (137, 2, '-d 옵션', '`docker run -d nginx` 에서 `-d` 는 무엇을 뜻할까요?', 'detach 는 "떼어 내다"는 뜻이에요.', NULL, NULL, '[]', 'choice', '["컨테이너를 삭제한다", "컨테이너를 백그라운드에서 실행하고 터미널을 돌려준다", "컨테이너를 디버그 모드로 실행한다", "다운로드만 한다"]', 1, '`-d` 가 없으면 컨테이너의 출력이 터미널을 붙잡습니다. 서버를 띄울 때는 거의 항상 `-d` 를 씁니다.', NULL, NULL, NULL, NULL),
  (137, 3, '--name 옵션', '`docker run --name web nginx` 에서 `--name web` 은 무엇을 할까요?', '컨테이너를 부를 이름이에요.', NULL, NULL, '[]', 'choice', '["컨테이너에 `web` 이라는 이름을 붙인다 (같은 이름은 동시에 둘 수 없다)", "이미지 이름을 web 으로 바꾼다", "컨테이너 안의 사용자 이름을 정한다", "호스트의 이름을 바꾼다"]', 0, '이름을 붙이면 `docker logs web`, `docker stop web` 처럼 쓸 수 있어 편합니다. 이름이 이미 있으면 "container name is already in use" 오류가 나요.', NULL, NULL, NULL, NULL),
  (137, 4, '-p 8080:80 읽기', '`-p 8080:80` 에서 왼쪽 `8080` 과 오른쪽 `80` 은 각각 무엇일까요?', '왼쪽은 바깥, 오른쪽은 안이에요.', NULL, NULL, '[]', 'choice', '["왼쪽은 컨테이너 포트, 오른쪽은 호스트 포트", "둘 다 호스트 포트", "왼쪽은 TCP, 오른쪽은 UDP", "왼쪽은 내 컴퓨터(호스트)의 포트, 오른쪽은 컨테이너 안의 포트"]', 3, '이 설정이면 내 컴퓨터의 8080 으로 들어온 요청이 컨테이너 안의 80 으로 전달됩니다. 순서는 `호스트:컨테이너` 예요.', NULL, NULL, NULL, NULL),
  (137, 5, '-e 옵션', '`docker run -e MODE=prod app` 에서 `-e` 는 무엇을 할까요?', 'environment 의 첫 글자예요.', NULL, NULL, '[]', 'choice', '["컨테이너를 종료할 때 실행할 명령을 정한다", "컨테이너에서 에러 로그만 출력한다", "컨테이너 안의 프로그램에 환경 변수 `MODE=prod` 를 전달한다", "컨테이너를 암호화한다"]', 2, '앱의 설정(DB 주소, 모드 등)을 이미지를 다시 만들지 않고 바꿀 때 씁니다. 여러 개면 `-e` 를 여러 번 써요.', NULL, NULL, NULL, NULL),
  (137, 6, '-v 옵션', '`docker run -v /srv/data:/data app` 에서 `-v` 는 무엇을 할까요?', 'volume 의 첫 글자예요. 안과 밖을 이어요.', NULL, NULL, '[]', 'choice', '["컨테이너의 로그를 자세히 출력한다", "호스트의 `/srv/data` 폴더를 컨테이너 안의 `/data` 로 연결한다", "컨테이너의 버전을 정한다", "이미지를 압축한다"]', 1, '연결한 폴더에 쓴 데이터는 컨테이너를 지워도 호스트에 남습니다. 순서는 `호스트:컨테이너` 이고, `-p` 와 같아요.', NULL, NULL, NULL, NULL),
  (137, 7, '--rm 옵션', '`docker run --rm alpine echo hi` 에서 `--rm` 은 무엇을 할까요?', 'rm 은 remove 예요. 언제 지울까요?', NULL, NULL, '[]', 'choice', '["컨테이너가 종료되면 자동으로 삭제한다", "이미지를 삭제한다", "실행 중인 다른 컨테이너를 삭제한다", "로그 파일을 지운다"]', 0, '한 번 실행하고 끝나는 확인용 컨테이너에 알맞습니다. 이 옵션이 없으면 종료된 컨테이너가 `docker ps -a` 에 계속 쌓여요.', NULL, NULL, NULL, NULL),
  (137, 8, '-it 옵션', '`docker run -it ubuntu bash` 에서 `-it` 은 무엇을 가능하게 할까요?', 'i 는 입력, t 는 터미널이에요.', NULL, NULL, '[]', 'choice', '["컨테이너를 두 번 실행한다", "컨테이너 이미지를 최신으로 바꾼다", "컨테이너를 백그라운드로 보낸다", "터미널로 컨테이너 안에 직접 입력하며 사용할 수 있게 한다"]', 3, '`-i`(입력 유지)와 `-t`(터미널 할당)를 합친 것입니다. 쉘로 들어가 둘러볼 때 자주 쓰고, `exit` 로 나올 수 있어요.', NULL, NULL, NULL, NULL),
  (137, 9, '이미지 태그', '`docker run nginx` 처럼 태그를 쓰지 않으면 어떤 버전이 실행될까요?', '기본 태그 이름이 있어요.', NULL, NULL, '[]', 'choice', '["가장 오래된 버전", "버전이 없어서 실행되지 않는다", "`latest` 태그가 기본으로 쓰인다 (항상 최신이라는 보장은 없다)", "내 컴퓨터에 있는 아무 버전"]', 2, '운영에서는 `nginx:1.27` 처럼 버전을 고정하는 것이 안전합니다. `latest` 는 단지 이름이어서 시점에 따라 내용이 바뀔 수 있어요.', NULL, NULL, NULL, NULL),
  (137, 10, 'stop 과 rm 의 차이', '`docker stop web` 과 `docker rm web` 의 차이로 알맞은 것은 무엇일까요?', '멈추는 것과 지우는 것은 달라요.', NULL, NULL, '[]', 'choice', '["둘은 완전히 같다", "`stop` 은 컨테이너를 멈추지만 남겨 두고, `rm` 은 멈춘 컨테이너를 삭제한다", "`stop` 은 삭제하고 `rm` 은 멈춘다", "`rm` 은 이미지를 삭제한다"]', 1, '멈춘 컨테이너는 `docker ps -a` 에 남아 있고 다시 `start` 할 수 있습니다. 실행 중인 컨테이너는 먼저 멈춰야 지울 수 있어요(`rm -f` 는 한 번에).', NULL, NULL, NULL, NULL),
  (137, 11, 'exec 와 run 의 차이', '`docker exec -it web sh` 와 `docker run -it nginx sh` 의 차이로 알맞은 것은 무엇일까요?', '하나는 이미 있는 컨테이너 안으로 들어가요.', NULL, NULL, '[]', 'choice', '["`exec` 는 이미 실행 중인 컨테이너 안에서 명령을 실행하고, `run` 은 새 컨테이너를 만든다", "둘은 완전히 같다", "`exec` 는 새 컨테이너를 만들고 `run` 은 기존 컨테이너를 쓴다", "`exec` 는 이미지를 받는다"]', 0, '돌고 있는 서버의 상태를 보려면 `exec` 입니다. `run` 을 쓰면 서버와 무관한 새 컨테이너가 하나 더 생겨요.', NULL, NULL, NULL, NULL),
  (137, 12, 'images 와 ps 의 차이', '`docker images` 와 `docker ps` 가 보여 주는 것으로 알맞은 것은 무엇일까요?', '이미지는 설계도, 컨테이너는 실행 중인 물건이에요.', NULL, NULL, '[]', 'choice', '["`images` 는 실행 중인 목록, `ps` 는 이미지 목록", "둘 다 이미지 목록", "둘 다 컨테이너 목록", "`images` 는 내려받은 이미지 목록, `ps` 는 실행 중인 컨테이너 목록"]', 3, '이미지는 읽기 전용 설계도이고 컨테이너는 그것으로 만든 실행본입니다. 이미지 하나로 컨테이너를 여러 개 만들 수 있어요.', NULL, NULL, NULL, NULL),
  (137, 13, 'rmi 는 무엇을 지울까', '`docker rmi nginx` 는 무엇을 지울까요?', 'rmi 는 remove image 예요.', NULL, NULL, '[]', 'choice', '["실행 중인 컨테이너", "컨테이너의 로그", "내려받은 이미지", "도커 자체"]', 2, '컨테이너가 그 이미지를 쓰고 있으면 지워지지 않습니다. 먼저 `docker rm` 으로 컨테이너를 정리한 뒤 이미지를 지우세요.', NULL, NULL, NULL, NULL),
  (137, 14, 'run 이 터미널을 붙잡는다', '`docker run nginx` 를 실행했더니 터미널이 멈춘 것처럼 아무것도 입력되지 않습니다. 이유는 무엇일까요?', '컨테이너의 출력이 화면에 연결돼 있어요.', NULL, NULL, '[]', 'choice', '["도커가 고장 났기 때문이다", "컨테이너가 포그라운드로 실행되어 터미널에 붙어 있기 때문이다 (정상이다)", "이미지가 깨졌기 때문이다", "컴퓨터의 메모리가 부족하기 때문이다"]', 1, 'Ctrl+C 를 누르면 컨테이너가 멈춥니다. 계속 돌려 두려면 `docker run -d nginx` 처럼 `-d` 를 쓰세요.', NULL, NULL, NULL, NULL),
  (137, 15, '이미지만 받기', 'nginx 이미지를 **내려받기만** 하는 명령입니다. 빈칸을 채우세요.', '"끌어당기다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["pull", "get", "fetch", "download"]', NULL, '`pull` 은 레지스트리에서 이미지를 내려받습니다. `docker run` 은 이미지가 없으면 자동으로 pull 해요.', '[0]', 'docker {0} nginx', NULL, NULL),
  (137, 16, '백그라운드 실행', 'nginx 를 **백그라운드로** 실행하는 옵션입니다. 빈칸을 채우세요.', 'detach 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-d", "-b", "-r", "-q"]', NULL, '`-d` 를 쓰면 컨테이너 ID 한 줄만 출력하고 터미널이 돌아옵니다.', '[0]', 'docker run {0} nginx', NULL, NULL),
  (137, 17, '이름 붙이기', '컨테이너에 `web` 이라는 **이름을 붙이는** 옵션입니다. 빈칸을 채우세요.', '영어로 이름이에요.', NULL, NULL, '[]', 'fill', '["name", "id", "tag", "title"]', NULL, '이름은 컨테이너마다 겹치지 않아야 합니다. 같은 이름이 남아 있으면 `docker rm` 으로 먼저 지워야 해요.', '[0]', 'docker run --{0} web nginx', NULL, NULL),
  (137, 18, '컨테이너 쪽 포트', '내 컴퓨터의 `8080` 을 nginx 컨테이너 **안의 80 포트**로 연결하려고 합니다. 빈칸을 채우세요.', '`호스트:컨테이너` 순서에서 오른쪽이에요.', NULL, NULL, '[]', 'fill', '["80", "8080", "443", "3000"]', NULL, 'nginx 는 컨테이너 안에서 80 포트로 듣고 있으니 오른쪽이 `80` 이어야 합니다. 왼쪽은 내가 정하는 바깥 번호예요.', '[0]', 'docker run -p 8080:{0} nginx', NULL, NULL),
  (137, 19, '환경 변수 넘기기', '컨테이너에 **환경 변수 `MODE=prod` 를 넘기는** 올바른 모양입니다. 빈칸을 채우세요.', '`이름=값` 형태예요.', NULL, NULL, '[]', 'fill', '["MODE=prod", "MODE:prod", "$MODE", "--MODE=prod"]', NULL, '`-e 이름=값` 이 기본 모양입니다. 값에 공백이 있으면 따옴표로 감싸세요.', '[0]', 'docker run -e {0} nginx', NULL, NULL),
  (137, 20, '폴더 연결하기', '호스트의 `/data` 폴더를 컨테이너 안의 `/data` 로 **연결하는** 옵션입니다. 빈칸을 채우세요.', 'volume 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-v", "-p", "-e", "-d"]', NULL, '`-v 호스트경로:컨테이너경로` 입니다. 이렇게 연결한 폴더의 데이터는 컨테이너를 지워도 남아요.', '[0]', 'docker run {0} /data:/data nginx', NULL, NULL),
  (137, 21, '끝나면 자동 삭제', '컨테이너가 끝나면 **자동으로 삭제되게** 하는 옵션입니다. 빈칸을 채우세요.', 'remove 의 줄임말 rm 이에요.', NULL, NULL, '[]', 'fill', '["--rm", "--del", "--remove-all", "--clean"]', NULL, '확인용 컨테이너를 쌓지 않으려면 `--rm` 을 습관처럼 붙이세요. 옵션 앞의 하이픈은 두 개입니다.', '[0]', 'docker run {0} alpine echo hi', NULL, NULL),
  (137, 22, '멈춘 컨테이너까지 보기', '실행 중인 것뿐 아니라 **멈춘 컨테이너까지 모두** 보는 옵션입니다. 빈칸을 채우세요.', 'all 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-a", "-d", "-r", "-x"]', NULL, '컨테이너가 바로 끝나 버렸다면 `docker ps` 에는 보이지 않습니다. `-a` 로 종료 상태(Exited)를 확인하세요.', '[0]', 'docker ps {0}', NULL, NULL),
  (137, 23, '로그 따라가기', '컨테이너 `web` 의 로그를 **실시간으로 따라가며** 보는 옵션입니다. 빈칸을 채우세요.', 'follow 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-f", "-w", "-l", "-p"]', NULL, '`-f` 는 `tail -f` 와 같은 느낌입니다. 끝내려면 Ctrl+C 를 누르세요(컨테이너는 계속 실행됩니다).', '[0]', 'docker logs {0} web', NULL, NULL),
  (137, 24, '실행 중인 컨테이너 안으로', '이미 실행 중인 컨테이너 `web` 안에서 **쉘을 여는** 명령입니다. 빈칸을 채우세요.', '"실행하다(execute)"의 줄임말이에요.', NULL, NULL, '[]', 'fill', '["exec", "run-in", "enter", "login"]', NULL, '`exec` 는 새 컨테이너를 만들지 않고 기존 컨테이너 안에서 명령을 실행합니다. 서버 점검의 기본이에요.', '[0]', 'docker {0} -it web sh', NULL, NULL),
  (137, 25, '컨테이너 멈추기', '실행 중인 컨테이너 `web` 을 **멈추는** 명령입니다. 빈칸을 채우세요.', '"멈추다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["stop", "pause", "end", "halt-all"]', NULL, '`stop` 은 프로그램에 종료 신호를 보내 정리할 시간을 줍니다. 멈춘 뒤에도 컨테이너는 남아 있어요.', '[0]', 'docker {0} web', NULL, NULL),
  (137, 26, '받아서 실행하고 확인하기', 'nginx 를 받아 실행하고 접속을 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '받기 → 실행 → 목록 → 접속 확인 순서예요.', NULL, NULL, '[]', 'order', '["`docker pull nginx` 로 이미지를 받는다", "`docker run -d --name web -p 8080:80 nginx` 로 실행한다", "`docker ps` 로 컨테이너가 떠 있는지 본다", "`curl localhost:8080` 으로 응답을 확인한다"]', NULL, '실행한 뒤에는 `docker ps` 로 살아 있는지, `curl` 로 응답하는지 두 번 확인하세요. 하나만으로는 놓치는 문제가 있어요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (137, 27, '컨테이너와 이미지 정리하기', '더 이상 쓰지 않는 컨테이너와 이미지를 정리하는 순서입니다. 순서에 맞게 놓아 보세요.', '멈춤 → 컨테이너 삭제 → 이미지 확인 → 이미지 삭제 순서예요.', NULL, NULL, '[]', 'order', '["`docker stop web` 으로 컨테이너를 멈춘다", "`docker rm web` 으로 컨테이너를 삭제한다", "`docker images` 로 남은 이미지를 확인한다", "`docker rmi nginx` 로 이미지를 삭제한다"]', NULL, '이미지는 컨테이너가 쓰고 있는 동안 지워지지 않으므로 항상 컨테이너부터 정리합니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (137, 28, '안 뜨는 컨테이너 조사하기', '컨테이너가 바로 종료될 때의 조사 순서입니다. 순서에 맞게 놓아 보세요.', '목록 → 로그 → 원인 고치기 → 다시 실행 순서예요.', NULL, NULL, '[]', 'order', '["`docker ps -a` 로 종료된 컨테이너와 상태를 본다", "`docker logs web` 으로 종료 직전의 출력을 본다", "로그에서 찾은 원인(환경 변수, 포트 등)을 고친다", "`docker rm web` 으로 지우고 고친 설정으로 다시 `docker run` 한다"]', NULL, '종료된 컨테이너는 로그가 남아 있어 원인을 알려 줍니다. 이름이 겹치지 않게 지운 뒤 다시 실행하세요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (137, 29, '폴더와 환경 변수 붙여 실행', '호스트 폴더와 환경 변수를 붙여 컨테이너를 실행하고 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '폴더 준비 → 실행 → 연결 확인 → 로그 확인 순서예요.', NULL, NULL, '[]', 'order', '["`mkdir -p ~/data` 로 호스트 폴더를 만든다", "`docker run -d --name app -v ~/data:/data -e MODE=prod nginx` 로 실행한다", "`docker exec app ls /data` 로 폴더가 연결됐는지 본다", "`docker logs app` 으로 시작 로그를 확인한다"]', NULL, '연결할 폴더는 실행하기 전에 만들어 두는 것이 안전합니다. 설정이 잘 들어갔는지는 `exec` 와 `logs` 로 확인해요.', '[0, 1, 2, 3]', NULL, NULL, NULL);
